import { auth } from "wizard-auth";

export default async function scheduleLoad(args: { period: "week" | "month" }) {
  const user = auth.currentUser();
  if (!user || (user.role !== "owner" && user.role !== "staff")) {
    throw new Error("Access denied");
  }
