}

import { v } from "valibot";
import { query } from "@wizard/api";

export const busySlots = query(async ({ from, to }, { user }) => {
  // Fetch bookings in the interval
  const bookings = await db.booking.findMany({
    where: {
      starts_at: { gte: from, lte: to },
