// Visit confirmation card: после отправки формы записи — «карточка визита»: услуга, дата и время
// крупным шрифтом, статус «Ждём подтверждения» / «Подтверждено», действия «сохранить» и «повторить».
// Композиция: асимметричная сетка — слева детали визита (6 колонок), справа узкая карточка статуса (5 колонок).
type Link = { label: string; href: string };

export type VisitConfirmationCardProps = {
  title: string;
  service: string;
  doctor?: string | null;
  date: string;
  time: string;
  status: 'pending' | 'confirmed';
  statusPendingLabel: string;
  statusConfirmedLabel: string;
  note?: string;
  saveAction: Link;
  repeatAction: Link;
};

export default function VisitConfirmationCard({
  title,
  service,
  doctor,
  date,
  time,
  status,
  statusPendingLabel,
  statusConfirmedLabel,
  note,
  saveAction,
  repeatAction,
}: VisitConfirmationCardProps) {
  const confirmed = status === 'confirmed';
  const statusLabel = confirmed ? statusConfirmedLabel : statusPendingLabel;

  return (
    <section className="bg-background font-sans text-foreground" id="visit-confirmation">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12 lg:gap-12">
          {/* Детали визита */}
          <div className="min-w-0 lg:col-span-7">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>

            <dl className="mt-8 grid grid-cols-1 gap-6 sm:grid-cols-2">
              <div className="min-w-0">
                <dt className="text-small text-muted-foreground">Услуга</dt>
                <dd className="mt-1 text-lead font-semibold wrap-break-word">{service}</dd>
              </div>
              {doctor ? (
                <div className="min-w-0">
                  <dt className="text-small text-muted-foreground">Врач</dt>
                  <dd className="mt-1 text-lead font-semibold wrap-break-word">{doctor}</dd>
                </div>
              ) : null}
              <div className="min-w-0">
                <dt className="text-small text-muted-foreground">Дата</dt>
                <dd className="mt-1 font-display text-h1 font-bold text-balance wrap-break-word">{date}</dd>
              </div>
              <div className="min-w-0">
                <dt className="text-small text-muted-foreground">Время</dt>
                <dd className="mt-1 font-display text-h1 font-bold text-balance wrap-break-word">{time}</dd>
              </div>
            </dl>

            {note ? <p className="mt-8 max-w-text text-body text-muted-foreground wrap-break-word">{note}</p> : null}

            <div className="mt-8 flex flex-col gap-3 sm:flex-row">
              <a
                href={saveAction.href}
                className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {saveAction.label}
              </a>
              <a
                href={repeatAction.href}
                className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control border border-border bg-card px-6 text-center text-body font-bold text-card-foreground transition-colors duration-200 hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {repeatAction.label}
              </a>
            </div>
          </div>

          {/* Карточка статуса */}
          <aside className="lg:col-span-5">
            <div className="rounded-lg border border-border bg-card p-8 text-card-foreground min-w-0">
              <p className="text-small text-muted-foreground">Статус записи</p>
              <div className="mt-4 flex items-center gap-3">
                <span
                  aria-hidden="true"
                  className={
                    'inline-block size-3 shrink-0 rounded-sm ' +
                    (confirmed ? 'bg-primary' : 'bg-muted-foreground')
                  }
                />
                <p className="font-display text-h3 font-bold text-balance wrap-break-word">{statusLabel}</p>
              </div>
              <span
                aria-label={statusLabel}
                role="status"
                className={
                  'mt-6 inline-flex min-h-11 items-center rounded-control px-4 text-small font-semibold ' +
                  (confirmed
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted text-muted-foreground')
                }
              >
                {statusLabel}
              </span>
            </div>
          </aside>
        </div>
      </div>
    </section>
  );
}

